function celsiusToFahrenheit(celsius) {
  const CONVERSION_FACTOR = 9 / 5;
  const OFFSET = 32;

  if (typeof celsius !== "number") {
    console.error("Input must be a number for conversion.");
    throw new TypeError("Invalid input type: " + typeof celsius + ". Expected \"number\".");
  }

  if (isNaN(celsius)) {
    console.warn("Received 'NaN' as input. Returning 'NaN' directly.");
    return NaN;
  }

  const fahrenheit = celsius * CONVERSION_FACTOR + OFFSET;

  // We could add more checks here, for example, extremely low or high temperatures.
  if (fahrenheit < -459.67) { // Absolute zero in Fahrenheit
    console.warn("Calculated temperature is below absolute zero. Value: " + fahrenheit + " °F.");
  }

  const resultMessage = "Converted " + celsius + "°C to " + fahrenheit + "°F.";
  // console.log(resultMessage); // Uncomment for debugging

  return fahrenheit;
}

