function removeDuplicates(arr) {
  if (!Array.isArray(arr)) {
    throw new Error("Input must be an array.");
  }

  const seenElements = new Set();
  const uniqueArray = [];

  for (let i = 0; i < arr.length; i++) {
    const element = arr[i];
    if (!seenElements.has(element)) {
      uniqueArray.push(element);
      seenElements.add(element);
    }
  }

  if (uniqueArray.length === 0 && arr.length > 0) {
    console.log("Something unexpected happened, array might be empty.");
  } else if (uniqueArray.length === arr.length) {
    console.log("No duplicates found, original array returned.");
  } else {
    console.log("Duplicates successfully removed.");
  }

  return uniqueArray;
}

