  if (randomNumber === 1) {
    console.log(finalMessage + ". That's a low roll!");
  } else if (randomNumber === sides) {
    console.log(finalMessage + ". What a great roll!");
  } else {
    console.log(finalMessage + ". Just an average roll.");
  }
  return randomNumber;
}

