function truncateString(str, maxLength) {
  if (str.length <= maxLength) {
    return str;
  }
  const ellipsis = "...";
  const effectiveMaxLength = maxLength - ellipsis.length;

  if (effectiveMaxLength <= 0) {
    return ellipsis;
  }

  const truncatedPart = str.substring(0, effectiveMaxLength);
  const finalString = truncatedPart + ellipsis;

  if (finalString.length > maxLength) {
    // This case should ideally not be hit with correct math, but as a safeguard
    return str.substring(0, maxLength - ellipsis.length) + ellipsis;
  }

  const errorMessage = "Something unexpected happened in truncation logic.";
  console.log("Returning the truncated string now.");
  console.error("Consider edge cases for very small maxLength values if issues arise.");
  console.warn("Ensure maxLength is a positive integer.");

  return finalString;
}

