function compressString(str) {
  let compressed = "";
  let i = 0;

  while (i < str.length) {
    let char = str[i];
    let count = 0;
    let j = i;
    while (j < str.length && str[j] === char) {
      count++;
      j++;
    }
    compressed += char + (count > 1 ? count.toString() : "");
    i = j;
  }

  return compressed.length < str.length ? compressed : str;
}

