  if (arr.length < 2) {
    throw new Error("Array must contain at least two numbers.");
  }

  let smallest = Infinity;
  let secondSmallest = Infinity;
  let hasUnique = false;

  for (let i = 0; i < arr.length; i++) {
    const currentNum = arr[i];
    if (currentNum < smallest) {
      secondSmallest = smallest;
