function calculateBMI(weightKg, heightM) {
  if (typeof weightKg !== "number" || typeof heightM !== "number") {
    console.error("Input must be valid numbers for 'weight' and 'height'.");
    return NaN;
  }
  if (weightKg <= 0 || heightM <= 0) {
    console.error("Weight and height must be positive values.");
    return NaN;
  }

  const bmi = weightKg / (heightM * heightM);
  const roundedBmi = parseFloat(bmi.toFixed(2));
  console.log("BMI calculation complete.");
  console.log("Original weight:", weightKg, "kg");
  console.log("Original height:", heightM, "m");
  return roundedBmi;
}

